WITH net_loss_per_emp AS ( SELECT cc.cc_call_center_id AS call_center_id, cc.cc_name AS call_center_name, sm.sm_type AS ship_mode_type, w.w_warehouse_name AS warehouse_name, cc.cc_employees AS employee_count, SUM(cr.cr_net_loss) AS total_net_loss, SUM(cr.cr_net_loss) / NULLIF(cc.cc_employees, 0) AS net_loss_per_employee FROM catalog_returns cr JOIN call_center cc ON cr.cr_call_center_sk = cc.cc_call_center_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY cc.cc_call_center_id, cc.cc_name, sm.sm_type, w.w_warehouse_name, cc.cc_employees ) SELECT call_center_id, call_center_name, ship_mode_type, warehouse_name, net_loss_per_employee, CASE WHEN net_loss_per_employee > 100 THEN 'High' ELSE 'Moderate' END AS loss_category FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY call_center_id ORDER BY net_loss_per_employee DESC) AS rn FROM net_loss_per_emp ) t WHERE rn <= 3 ORDER BY call_center_id, rn
